package vendor

import (
	"fmt"
	"strings"

	"github.com/eyelock/ynh/internal/plugin"
)

// How an on_session_start hook's output reaches the model differs by vendor:
// Claude Code and Codex take plain stdout as context, while Copilot and Cursor
// ignore plain stdout and read one JSON field. A harness author writes plain
// text; ynh makes that true everywhere by wrapping the hook on the vendors that
// need a field (SessionContextScript). Each vendor declares which it is, as
// <x>SessionStartContext in its adapter file, and scripts/hook-event-parity.sh
// requires one of three forms of every vendor:
//
//	plain               stdout is model context as written
//	json-field:<name>   stdout is ignored; JSON {"<name>": "..."} is context
//	unsupported:<why>   no way to reach the model; a hook is warned about
//
// An undeclared vendor cannot compile into the table below.
var sessionStartContext = map[string]string{
	"claude":   claudeSessionStartContext,
	"codex":    codexSessionStartContext,
	"copilot":  copilotSessionStartContext,
	"cursor":   cursorSessionStartContext,
	"opencode": opencodeSessionStartContext,
}

const (
	sessionStartPlain       = "plain"
	sessionStartFieldPrefix = "json-field:"
	sessionStartNoPrefix    = "unsupported:"

	// SessionContextScript is where the wrapper lives, relative to the root a
	// vendor's hook commands are anchored to: the plugin root in an export,
	// the run directory's plugin root (or the run directory itself, for a
	// vendor without one) in a session.
	SessionContextScript = "hooks/ynh-session-context.sh"

	// sessionContextBoth is the wrapper mode for a package that Claude Code
	// and Copilot share one hook file for: it emits both shapes.
	sessionContextBoth = "claude+copilot"
)

// sessionContextMode is the wrapper mode for a vendor: its field, or "" when
// the vendor needs no wrapper.
func sessionContextMode(vendorName string) string {
	decl := sessionStartContext[vendorName]
	if !strings.HasPrefix(decl, sessionStartFieldPrefix) {
		return ""
	}
	return strings.TrimPrefix(decl, sessionStartFieldPrefix)
}

// sessionContextWarnings reports a vendor that declares no way for
// on_session_start output to reach the model.
func sessionContextWarnings(vendorName string, hooks map[string][]plugin.HookEntry) []string {
	if len(hooks["on_session_start"]) == 0 {
		return nil
	}
	reason, ok := strings.CutPrefix(sessionStartContext[vendorName], sessionStartNoPrefix)
	if !ok {
		return nil
	}
	return []string{fmt.Sprintf("on_session_start output does not reach the model on %s: %s", vendorName, reason)}
}

// sessionCommand renders one hook command for a vendor document. For
// on_session_start with a wrapper mode it runs the command through the wrapper
// (anchored like any "./" script); everything else is the anchored command.
func sessionCommand(mode, event, cmd string, anchor func(string) string) string {
	if event != "on_session_start" || mode == "" {
		return anchor(cmd)
	}
	return "sh " + anchor("./"+SessionContextScript) + " " + mode + " " + shellQuote(anchor(cmd))
}

func shellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

// sessionContextFiles adds the wrapper to a hook file set when the document
// uses it. rel is where the wrapper sits relative to what the files map is
// written under.
func sessionContextFiles(files map[string][]byte, rel, mode string, hooks map[string][]plugin.HookEntry) {
	if mode == "" || len(hooks["on_session_start"]) == 0 || files == nil {
		return
	}
	files[rel] = []byte(sessionContextScript)
}

// sessionContextScript is the wrapper: POSIX sh and awk only, so it runs on a
// machine that has neither ynh, python nor jq. It runs the command with this
// script's stdin and stderr, keeps its exit status, and turns its stdout into
// {"<field>": "<stdout>"}. Output that is already a JSON object passes through
// unchanged, and empty output emits nothing. Bytes pass through untouched
// (LC_ALL=C), so UTF-8 survives; quotes, backslashes and control characters
// are escaped.
const sessionContextScript = `#!/bin/sh
# Generated by ynh. Runs an on_session_start hook command and turns its plain
# stdout into the JSON field the vendor reads as model context.
#   usage: ynh-session-context.sh <field> <command>
# <field> is the JSON key to emit, or claude+copilot for a package both read.
field=$1
cmd=$2
tmp=$(mktemp "${TMPDIR:-/tmp}/ynh-session-context.XXXXXX") || exit 1
trap 'rm -f "$tmp"' EXIT
sh -c "$cmd" >"$tmp"
status=$?
LC_ALL=C awk -v field="$field" '
function esc(s,   i, n, c, o) {
  n = length(s); o = ""
  for (i = 1; i <= n; i++) {
    c = substr(s, i, 1)
    if (c == "\\") o = o "\\\\"
    else if (c == "\"") o = o "\\\""
    else if (c == "\t") o = o "\\t"
    else if (c == "\r") o = o "\\r"
    else if (c in ctl) o = o ctl[c]
    else o = o c
  }
  return o
}
BEGIN { for (i = 1; i < 32; i++) ctl[sprintf("%c", i)] = sprintf("\\u%04x", i) }
{ line[NR] = $0 }
END {
  n = NR
  while (n > 0 && line[n] ~ /^[ \t\r]*$/) n--
  if (n == 0) exit
  text = line[1]
  for (i = 2; i <= n; i++) text = text "\n" line[i]
  if (text ~ /^[ \t\r\n]*\{/ && text ~ /\}[ \t\r\n]*$/) { print text; exit }
  body = ""
  for (i = 1; i <= n; i++) body = body (i > 1 ? "\\n" : "") esc(line[i])
  if (field == "claude+copilot")
    printf "{\"additionalContext\":\"%s\",\"hookSpecificOutput\":{\"hookEventName\":\"SessionStart\",\"additionalContext\":\"%s\"}}\n", body, body
  else
    printf "{\"%s\":\"%s\"}\n", field, body
}' "$tmp"
exit "$status"
`
